import { useState, type FormEvent } from 'react';
import { Button, Field, Input, Select, Switch } from '@jinx-ui/react';

export type ProfileSettings = {
  name: string;
  language: 'ru' | 'en';
  emailNotifications: boolean;
};

type ProfileSettingsFormProps = {
  onSave: (settings: ProfileSettings) => void;
  initialSettings?: Partial<ProfileSettings>;
};

const LANGUAGE_OPTIONS = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'Английский' },
];

export default function ProfileSettingsForm({ onSave, initialSettings }: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState<ProfileSettings['language']>(initialSettings?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(initialSettings?.emailNotifications ?? false);

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSave({ name: name.trim(), language, emailNotifications });
  }

  return (
    <form
      className="jx-form jx-stack"
      style={{ gap: 'var(--jx-space-4)', maxWidth: 'var(--jx-size-form)' }}
      onSubmit={handleSubmit}
    >
      <Field label="Имя" htmlFor="profile-name">
        <Input
          id="profile-name"
          className="jx-input"
          value={name}
          onValueChange={setName}
          placeholder="Введите имя"
          autoComplete="name"
        />
      </Field>

      <Field label="Язык интерфейса" htmlFor="profile-language">
        <Select
          id="profile-language"
          className="jx-select"
          value={language}
          onValueChange={(value: string) => setLanguage(value as ProfileSettings['language'])}
          options={LANGUAGE_OPTIONS}
        />
      </Field>

      <Field label="Уведомления на почту" htmlFor="profile-notifications">
        <Switch
          id="profile-notifications"
          className="jx-switch"
          checked={emailNotifications}
          onCheckedChange={setEmailNotifications}
        />
      </Field>

      <Button type="submit" className="jx-btn jx-btn--primary">
        Сохранить
      </Button>
    </form>
  );
}

